/** In-app notifications — contract §0.5, §10. */
export const NOTIFICATION_KINDS = ["ASSIGN", "ASK", "ANSWER", "RECALL", "APPROVAL", "DUE", "FINAL", "INFO"] as const;
export type NotificationKind = (typeof NOTIFICATION_KINDS)[number];

export interface Notification {
  id: number;
  kind: NotificationKind;
  requestId: string | null;
  text: string;
  createdAt: string;
  read: boolean;
  /** Generated by the reminder schedule (24h interval, max 3). */
  renotify: boolean;
  /** The user still has work to do on the request. */
  pending: boolean;
}

export interface NotificationList {
  unreadCount: number;
  items: Notification[];
}
